-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS stock_ledger_entries_update_audit ON inventory.stock_ledger_entries;
CREATE TRIGGER stock_ledger_entries_update_audit BEFORE UPDATE ON inventory.stock_ledger_entries
